  transmute(SOC = soc6, `Intitulé SOC` = intitule_soc, `ISCO-08` = isco08,
            `Intitulé ISCO-08` = intitule_isco, `Fonction publique (rapprochement)` = fonction_publique,
            `Activités communes` = argument) |>
  gt::gt() |>
